import { Log, useTranslation } from '@fanfanlo';
import { Box, CircularProgress, Typography, Button } from '@mui/material';

const fileLog = new Log(false, 'MarketStateComponents_f');

export interface IMarketLoadingStateProps {
    testId?: string;
}

export function MarketLoadingState({ testId }: IMarketLoadingStateProps) {
    const uiLog = fileLog.sub(false, 'MarketLoadingState_ui');
    uiLog.log('[MarketLoadingState] 渲染加载状态');

    return (
        <Box
            sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%' }}
            data-testid={testId || 'MarketLoadingState__box__01jw8k9m2n3p4q5r6s7t8u9y'}
            data-test-comment="市场列表加载中状态"
        >
            <CircularProgress />
        </Box>
    );
}

export interface IMarketErrorStateProps {
    errorMsg: string;
    onRetry: () => void;
    testId?: string;
}

export function MarketErrorState({ errorMsg, onRetry, testId }: IMarketErrorStateProps) {
    const uiLog = fileLog.sub(false, 'MarketErrorState_ui');
    const { t } = useTranslation('droid-project-v2-ui/ui/market/content');

    uiLog.log('[MarketErrorState] 渲染错误状态, errorMsg:', errorMsg);

    let displayErrorMsg = errorMsg;
    if (!displayErrorMsg) {
        displayErrorMsg = t('MarketStateComponents.MarketContainer.loadFailed');
    }

    return (
        <Box
            sx={{ textAlign: 'center', py: 4 }}
            data-testid={testId || 'MarketErrorState__box__01jw8k9m2n3p4q5r6s7t8u9z'}
            data-test-comment="市场列表错误状态"
        >
            <Typography color="error" gutterBottom>
                {displayErrorMsg}
            </Typography>
            <Button
                variant="contained"
                onClick={onRetry}
                data-testid="MarketErrorState__retryButton__01jw8k9m2n3p4q5r6s7t8ua0"
                data-test-comment="重试按钮，点击后重新加载市场项目列表"
            >
                {t('MarketStateComponents.MarketContainer.retry')}
            </Button>
        </Box>
    );
}

