import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { Log } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";

const fileLog = new Log(false, 'nextPage_f');
// fileLog.pause = true;

/**
 * 获取市场分页数据的请求参数
 */
export interface INextPageParams extends IRequestParams {
    category?: string;           // 分类，默认"public"
    currentPageIndex?: number;   // 当前页码，可选，不传从最新页开始
}

/**
 * 获取市场分页数据的返回结果
 */
export interface INextPageResult extends IResultContent {
    is_ok: boolean;
    msg?: string;
    pageIndex: number;    // 返回的起始页码
    urls: string[];       // CDN URL列表
}

/**
 * 获取市场项目分页数据
 * 
 * 功能说明：
 * - 获取公开项目市场的分页CDN URL列表
 * - 不传currentPageIndex时从最新页开始
 * - 传入currentPageIndex时从currentPageIndex-1开始
 * 
 * @param opts 请求选项
 * @returns 查询结果，包含pageIndex和urls列表
 */
export async function nextPage(opts: IRequestOptions<INextPageParams>) {
    const fnLog = fileLog.sub(false, 'nextPage_fn');
    // fnLog.pause = true;

    fnLog.log('[nextPage] 开始获取市场分页数据, params:', JSON.stringify(opts.params));

    const res = await request<INextPageResult>(
        tms.TProject,
        tms.MProjectNextPage,
        opts.params,
        opts.gateway,
        opts.handler
    );

    fnLog.log('[nextPage] 请求完成, shellIsOk:', res.shellIsOk, 'dataIsOk:', res.dataIsOk);

    if (!res.shellIsOk) {
        fnLog.log('[nextPage] ERROR: 请求失败, err:', JSON.stringify(res.err));
    }

    if (!res.dataIsOk) {
        fnLog.log('[nextPage] ERROR: 数据异常, errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.is_ok) {
            fnLog.log('[nextPage] 获取成功, pageIndex:', res.data.pageIndex, 'urls数量:', res.data.urls?.length);
        } else {
            fnLog.log('[nextPage] ERROR: 获取失败, msg:', res.data.msg);
        }
    } else {
        fnLog.log('[nextPage] ERROR: 无返回数据');
    }

    return res;
}

export default nextPage;
