/**
 * Project API 类型定义
 *
 * 使用 Partial + Omit 方式基于 IProject 创建 Input 类型
 * 保证字段与 @droid/project-v2-interface 对齐
 *
 * 对应后端：C:\work\android-droid\go\routers\project\create_project.go
 */
import type {
    IProject,
    ITriggerActionGroup,
    ITriggerAction,
    ITriggerGroup,
    IActionGroup,
    ITrigger,
    IAction
} from '@droid/project-v2-interface';

// ============================================================================
// 返回类型别名（与后端命名一致）
// ============================================================================

export type IProjectProject = IProject;
export type IProjectTriggerActionGroup = ITriggerActionGroup;
export type IProjectTriggerAction = ITriggerAction;
export type IProjectTriggerGroup = ITriggerGroup;
export type IProjectActionGroup = IActionGroup;
export type IProjectTrigger = ITrigger;
export type IProjectAction = IAction;

// ============================================================================
// 输入类型（创建/更新 API 使用）
// ============================================================================

/**
 * 创建 Trigger 的输入类型
 * 基于 ITrigger，排除后端生成的字段
 */
export type ITriggerInput =
    Partial<Omit<ITrigger, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid'>>
    & {
        type: string;  // 必填：触发器类型
    };

/**
 * 创建 Action 的输入类型
 * 基于 IAction，排除后端生成的字段
 */
export type IActionInput =
    Partial<Omit<IAction, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid'>>
    & {
        type: string;  // 必填：动作类型
    };

/**
 * 创建 TriggerGroup 的输入类型
 * 基于 ITriggerGroup，排除后端生成的字段
 */
export type ITriggerGroupInput =
    Partial<Omit<ITriggerGroup, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        children?: ITriggerInput[];
    };

/**
 * 创建 ActionGroup 的输入类型
 * 基于 IActionGroup，排除后端生成的字段
 */
export type IActionGroupInput =
    Partial<Omit<IActionGroup, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        children?: IActionInput[];
    };

/**
 * 创建 TriggerAction 的输入类型
 * 基于 ITriggerAction，排除后端生成的字段
 */
export type ITriggerActionInput =
    Partial<Omit<ITriggerAction, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'triggerGroup' | 'actionGroup'>>
    & {
        triggerGroup?: ITriggerGroupInput;
        actionGroup?: IActionGroupInput;
    };

/**
 * 创建 TriggerActionGroup 的输入类型
 * 基于 ITriggerActionGroup，排除后端生成的字段
 */
export type ITriggerActionGroupInput =
    Partial<Omit<ITriggerActionGroup, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        children?: ITriggerActionInput[];
    };

/**
 * 创建 Project 的输入类型
 * 基于 IProject，排除后端生成的字段
 */
export type IProjectInput =
    Partial<Omit<IProject, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children' | 'triggerActionGroup'>>
    & {
        type: string;           // 必填：项目类型
        category: string;       // 必填：项目分类
        visibility: string;     // 必填：可见性 'public' | 'private'
        children?: ITriggerActionGroupInput[];
    };

/**
 * 更新 Project 的输入类型
 * uuid 必填（更新依据），其他字段可选
 */
export type IProjectUpdateInput =
    Partial<Omit<IProject, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children' | 'triggerActionGroup'>>
    & {
        uuid: string;           // 必填：更新依据
        children?: ITriggerActionGroupInput[];
    };

// ============================================================================
// 更新类型（Update API 使用）
// ============================================================================

/**
 * 更新 TriggerActionGroup 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateTriggerActionGroupInput =
    Partial<Omit<ITriggerActionGroup, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        children?: IUpdateTriggerActionInput[];
    };

/**
 * 更新 TriggerAction 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateTriggerActionInput =
    Partial<Omit<ITriggerAction, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'triggerGroup' | 'actionGroup'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        triggerGroup?: IUpdateTriggerGroupInput;
        actionGroup?: IUpdateActionGroupInput;
    };

/**
 * 更新 TriggerGroup 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateTriggerGroupInput =
    Partial<Omit<ITriggerGroup, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        children?: IUpdateTriggerInput[];
    };

/**
 * 更新 ActionGroup 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateActionGroupInput =
    Partial<Omit<IActionGroup, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        children?: IUpdateActionInput[];
    };

/**
 * 更新 Trigger 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateTriggerInput =
    Partial<Omit<ITrigger, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        type?: string;  // 可选：更新时可以不提供
    };

/**
 * 更新 Action 的输入类型
 * 有 uuid 则更新，无 uuid 则创建
 */
export type IUpdateActionInput =
    Partial<Omit<IAction, 'id' | 'createdAt' | 'updatedAt' | 'ownerUuid'>>
    & {
        uuid?: string;  // 可选：有则更新，无则创建
        type?: string;  // 可选：更新时可以不提供
    };

/**
 * 更新 Project 的返回结果
 */
export interface IUpdateProjectResult {
    isOk: boolean;
    msg: string;
    project?: IProjectProject;
    changes?: Record<string, any>;  // 变更记录
    deletedChildren?: string[];     // 被软删除的子级 UUID
    createdChildren?: string[];     // 新创建的子级 UUID
    oldVisibility?: string;         // 旧的 visibility，用于分页更新判断
}

/**
 * 更新 Project 的数据类型
 * 基于 IProject，排除后端生成的字段和不可修改的字段
 * uuid 必填（更新依据）
 */
export type IUpdateProjectData =
    Partial<Omit<IProject, 'id' | 'uuid' | 'createdAt' | 'updatedAt' | 'ownerUuid' | 'children' | 'triggerActionGroup'>>
    & {
        uuid: string;  // 必填：更新依据
        children?: IUpdateTriggerActionGroupInput[];
    };

// ============================================================================
// 个人项目列表分页查询类型
// ============================================================================

/**
 * 最新同步的project信息（用于增量同步）
 */
export interface ILatestSyncedProject {
    uuid: string;           // project的uuid
    updatedAt: number;      // 最后更新时间戳（毫秒）
    version: number;        // 项目版本
    childrenVersion: number; // 子项目版本
}

/**
 * 个人项目列表分页查询的请求参数
 */
export interface IListUserProjectsParams {
    pageSize?: number;                          // 可选：每页数据量，默认 30
    latestSyncedProject?: ILatestSyncedProject; // 可选：最新同步的project信息（用于增量同步）
}

/**
 * 个人项目列表分页查询的返回结果
 */
export interface IListUserProjectsResult {
    is_ok: boolean;
    msg?: string;
    urls: string[];                    // R2 URL 列表（公开项目为 CDN URL，私有项目为预签名 URL）
    lastProjectUuid: string;           // 下次查询的游标（最后一条项目的 UUID）
    hasMore: boolean;                  // 是否有更多数据
    isLast: boolean;                   // 是否是最后一页
    lastProjectInfo?: {                // 获取到的最后一个project的信息（用于下次查询）
        uuid: string;                  // project的uuid
        updatedAt: number;             // 最后更新时间戳（毫秒）
        version: number;               // 项目版本
        childrenVersion: number;       // 子项目版本
    };
}

/**
 * 个人项目列表分页查询的完整返回结果
 */
export interface IListUserProjectsFullResult {
    isOk: boolean;
    msg?: string;
    data?: {
        urls: string[];                // R2 URL 列表
        lastProjectUuid: string;       // 下次查询的游标
        hasMore: boolean;              // 是否有更多数据
        isLast: boolean;               // 是否是最后一页
    };
}

// ============================================================================
// 删除 Project 类型
// ============================================================================

/**
 * 删除 Project 的输入类型
 */
export interface IDeleteProjectInput {
    uuid: string;  // 必填：要删除的 Project UUID
}

/**
 * 删除 Project 的返回结果
 */
export interface IDeleteProjectResult {
    is_ok: boolean;
    msg?: string;
    uuid?: string;      // 被删除的 Project UUID
    deletedAt?: number; // 删除时间戳（毫秒）
}

// ============================================================================
// 市场项目类型
// ============================================================================

/**
 * 市场项目摘要信息（来自R2分页数据）
 */
export interface IMarketProjectSummary {
    uuid: string;
    title: string;
    subtitle: string | null;
    thumbnailPath: string | null;
    ownerUuid: string;
    authorUuid: string;
    tags: string[];
    categories: string[];
    createdAt: number;
    updatedAt: number;
}

/**
 * R2分页数据结构
 */
export interface IR2PageData {
    category: string;
    pageIndex: number;
    pageSize: number;
    totalCount: number;
    totalPages: number;
    hasMore: boolean;
    projects: IMarketProjectSummary[];
    version: number;
    generatedAt: number;
}

/**
 * 市场加载状态枚举
 */
export enum MarketLoadingState {
    Idle = 'idle',
    Loading = 'loading',
    Error = 'error',
    Success = 'success'
}

/**
 * 市场数据状态
 */
export interface IMarketState {
    projects: IMarketProjectSummary[];
    currentPageIndex: number;
    hasMore: boolean;
    loadingState: MarketLoadingState;
    errorMsg: string;
}
