import { Log, useTranslation } from '@fanfanlo';
import { Box, Card, CardContent, Chip, Typography, Button, Stack } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import Link from 'next/link';
import { IMarketProjectSummary } from '@app/model';

const fileLog = new Log(false, 'MarketProjectCard_f');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

export interface IMarketProjectCardProps {
    project: IMarketProjectSummary;
    index: number;
}

export function MarketProjectCard({ project, index }: IMarketProjectCardProps) {
    const uiLog = fileLog.sub(false, 'MarketProjectCard_ui');
    // uiLog.pause = true;
    // uiLog.childrenPaused = true;

    const { t } = useTranslation('droid-project-v2-ui/ui/market/content');

    uiLog.log('[MarketProjectCard] index:', index, 'uuid:', project.uuid, 'title:', project.title);

    let displayTitle = project.title;
    if (!displayTitle) {
        displayTitle = t('MarketProjectCard.untitled');
    }

    const editHref = `/project-editor?mode=market&uuid=${project.uuid}`;

    return (
        <Card
            sx={{ width: '100%', mb: 1 }}
            data-testid={`MarketProjectCard__card__01jw8k9m2n3p4q5r6s7t8u9v__${index}`}
            data-test-comment="市场项目卡片，展示项目标题、副标题、标签和操作按钮"
        >
            <CardContent>
                {/* 标题 */}
                <Typography variant="h6" component="div" gutterBottom>
                    {displayTitle}
                </Typography>

                {/* 副标题 */}
                {project.subtitle && (
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                        {project.subtitle}
                    </Typography>
                )}

                {/* 标签 */}
                {project.tags && project.tags.length > 0 && (
                    <Box sx={{ mb: 1 }}>
                        {project.tags.map((tag, tagIndex) => (
                            <Chip
                                key={tagIndex}
                                label={tag}
                                size="small"
                                sx={{ mr: 0.5, mb: 0.5 }}
                            />
                        ))}
                    </Box>
                )}

                {/* 操作按钮 */}
                <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
                    <Link href={editHref} passHref legacyBehavior>
                        <Button
                            component="a"
                            size="small"
                            variant="contained"
                            startIcon={<EditIcon />}
                            data-testid={`MarketProjectCard__editButton__01jw8k9m2n3p4q5r6s7t8u9v__${index}`}
                            data-test-comment="编辑按钮，点击后进入编辑页面编辑该市场项目"
                        >
                            {t('MarketProjectCard.edit')}
                        </Button>
                    </Link>
                </Stack>
            </CardContent>
        </Card>
    );
}
