import { Log, useProxyWatch, useProxyWatchUpdates } from '@fanfanlo';
import { Box } from '@mui/material';
import { useCallback, useRef } from 'react';
import { Virtuoso } from 'react-virtuoso';
import { MarketProjectCard } from './MarketProjectCard';
import { marketState, loadMarketProjects } from './marketState';
import { MarketLoadingState } from '@app/model';
import {
    MarketLoadingState as MarketLoadingStateUI,
    MarketErrorState,
    MarketEmptyState,
    MarketFooterLoading,
    MarketFooterError,
    MarketFooterNoMore
} from './MarketStateComponents';

const fileLog = new Log(false, 'MarketProjectList_f');

export function MarketProjectList() {
    const uiLog = fileLog.sub(false, 'MarketProjectList_ui');

    const [projects] = useProxyWatchUpdates(marketState, 'projects', marketState.projects || []);
    const [loadingState] = useProxyWatch(marketState, 'loadingState', marketState.loadingState);
    const [hasMore] = useProxyWatch(marketState, 'hasMore', marketState.hasMore);
    const [errorMsg] = useProxyWatch(marketState, 'errorMsg', marketState.errorMsg);

    const projectsLength = projects.length;
    const isLoading = loadingState === MarketLoadingState.Loading;
    const isError = loadingState === MarketLoadingState.Error;
    const isSuccess = loadingState === MarketLoadingState.Success;

    uiLog.log('[MarketProjectList] projects:', projectsLength, 'loadingState:', loadingState, 'hasMore:', hasMore);

    const virtuosoRef = useRef<any>(null);

    const handleEndReached = useCallback(() => {
        const currentLoadingState = marketState.loadingState;
        const currentHasMore = marketState.hasMore;
        uiLog.log('[MarketProjectList] endReached, isLoading:', currentLoadingState === MarketLoadingState.Loading, 'hasMore:', currentHasMore);
        if (currentLoadingState === MarketLoadingState.Loading) {
            return;
        }
        if (!currentHasMore) {
            return;
        }
        loadMarketProjects(false);
    }, []);

    const handleRetry = () => {
        uiLog.log('[MarketProjectList] 点击重试');
        loadMarketProjects(true);
    };

    const hasNoProjects = projectsLength === 0;

    if (isLoading && hasNoProjects) {
        return <MarketLoadingStateUI />;
    }

    if (isError && hasNoProjects) {
        return <MarketErrorState errorMsg={errorMsg} onRetry={handleRetry} />;
    }

    if (hasNoProjects && isSuccess) {
        return <MarketEmptyState />;
    }

    return (
        <Virtuoso
            ref={virtuosoRef}
            style={{ height: '100%', width: '100%' }}
            data={projects}
            itemContent={(index, project) => (
                <Box sx={{ px: 1, py: 0.5 }}>
                    <MarketProjectCard
                        project={project}
                        index={index}
                    />
                </Box>
            )}
            endReached={handleEndReached}
            components={{
                EmptyPlaceholder: () => <MarketEmptyState />,
                Footer: () => {
                    const currentLoadingState = marketState.loadingState;
                    const currentHasMore = marketState.hasMore;
                    const currentIsLoading = currentLoadingState === MarketLoadingState.Loading;
                    const currentIsError = currentLoadingState === MarketLoadingState.Error;
                    const hasProjects = projectsLength > 0;

                    if (currentIsLoading && hasProjects) {
                        return <MarketFooterLoading />;
                    }

                    if (currentIsError && hasProjects) {
                        return <MarketFooterError errorMsg={marketState.errorMsg} onRetry={handleRetry} />;
                    }

                    if (!currentHasMore && hasProjects) {
                        return <MarketFooterNoMore />;
                    }

                    return null;
                }
            }}
        />
    );
}
