import { Log } from '@fanfanlo';
import { Box } from '@mui/material';
import { useEffect } from 'react';
import { MarketProjectList } from './MarketProjectList';
import { loadMarketProjects } from './marketState';

const fileLog = new Log(false, 'MarketContainer_f');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

export function MarketContainer() {
    const uiLog = fileLog.sub(false, 'MarketContainer_ui');
    // uiLog.pause = true;
    // uiLog.childrenPaused = true;

    useEffect(() => {
        const fnLog = uiLog.sub(false, 'effect_init_fn');
        // fnLog.pause = true;
        fnLog.log('[MarketContainer] useEffect 初始化加载');
        loadMarketProjects(true);
    }, []);

    return (
        <Box sx={{ height: '100%', width: '100%' }}>
            <MarketProjectList />
        </Box>
    );
}
